            "created_at": "Thu, 08/12/2021 - 21:37",
            "updated_at": "Wed, 09/29/2021 - 14:26",
            "body": "<p>Vokalizon dhe prodhon tinguj që i ngjajnë zanoreve - a, e, i, o, u</p>",
