            "type": "Milestone",
            "title": "Mund të thotë një fjali me 2 deri në 3 fjalë",
            "created_at": "Thu, 08/12/2021 - 21:37",
            "updated_at": "Wed, 09/29/2021 - 14:35",
            "body": "<p>Mund të formulojë dhe të thotë fjali me 2 deri në 3 fjalë aq mirë sa anëtarët e familjes mund ta kuptojnë atë.</p>",
