            "updated_at": "Wed, 09/22/2021 - 06:03",
            "body": "<p>Fillon të kuptojë kuptimin e fjalës \"jo\". Kur ai dëgjon fjalën, ai ndalon aktivitetin dhe njeh mosaprovimin.</p>",
