            "type": "Milestone",
            "title": "Kupton dhe realizon urdhëra të thjeshtë",
            "created_at": "Thu, 08/12/2021 - 21:37",
            "updated_at": "Wed, 09/22/2021 - 06:03",
            "body": "<p>Ndjek udhëzimet e thjeshta pa demonstrim, si dhe mund të kryejë atë që pritet prej tij.</p>",
            "child_age": [
                49
            ],
