            "body": "\u003Cp\u003EBiron jismga choʻziladi va bosh barmogʻini ishlatmay, kaftlarining tashqi tomoni bilan ushlaydi. Jismni silkitib, urib yoki ogʻziga solib boshqaradi\u003C/p\u003E",
