            "body": "\u003Cp\u003EGúrrińdiń tiykarǵı ideyaları yamasa súygen bólegin ǵárezsiz ayta aladı, úlken adamlarday oy-pikir ete aladı\u003C/p\u003E",
            "child_age": [57],
            "related_activities": [7491],
