            "type": "Milestone",
            "title": "Bir qolı menen oyınshıqqa shóp'ziladi, onı úyrenedi, jipekitadi hám irg'itadi",
            "created_at": "\u003Ctime datetime=\"2025-08-06T14:21:42+02:00\" class=\"datetime\"\u003EWed, 08/06/2025 - 14:21\u003C/time\u003E\n",
