            "body": "\u003Cp\u003EQandayda denege shóp'ziladi hám bas barmaǵın isletmay, alaqanlarınıń sırtqı tárepi menen uslaydı. Deneni silkip, urıp yamasa awızına salıp basqaradı\u003C/p\u003E",
