            "type": "Milestone",
            "title": "Jıǵılıp atırǵan ob'ektti baqlaydı hám jasırın buyımdı izleydi",
            "created_at": "\u003Ctime datetime=\"2025-08-06T14:18:02+02:00\" class=\"datetime\"\u003EWed, 08/06/2025 - 14:18\u003C/time\u003E\n",
