            "body": "\u003Cp\u003EBuyımlardı qoldan qolǵa Jumsaqlıq menen ótkeredi, olardı jipekitadi. Ol buyımlardı shep qolınan oń qolına hám kerisinshe háreketlendiriw arqalı basqaradı.\u003C/p\u003E",
